class Solution:
    def minSumSquareDiff(self, nums1: List[int], nums2: List[int], k1: int, k2: int) -> int:
        d = [abs(a - b) for a, b in zip(nums1, nums2)]
        K = k1 + k2
        cost = lambda x: sum(v - x for v in d if v > x)
        lo, hi = 0, max(d)
        while lo < hi:
            mid = (lo + hi) // 2
            if cost(mid) <= K:
                hi = mid
            else:
                lo = mid + 1
        x = lo
        big = [v for v in d if v >= x]
        ans = sum(v * v for v in d if v < x) + len(big) * x * x
        if x > 0:
            ans -= (K - cost(x)) * (2 * x - 1)
        return ans

