class Solution {
public:
    long long minSumSquareDiff(vector<int>& nums1, vector<int>& nums2, int k1, int k2) {
        int n = nums1.size();
        vector<long long> d(n);
        for (int i = 0; i < n; ++i) d[i] = abs(nums1[i] - nums2[i]);
        long long K = (long long)k1 + k2;
        auto cost = [&](long long x) {
            long long s = 0;
            for (long long v : d) if (v > x) s += v - x;
            return s;
        };
        long long lo = 0, hi = *max_element(d.begin(), d.end());
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (cost(mid) <= K) hi = mid; else lo = mid + 1;
        }
        long long x = lo, ans = 0, cnt = 0;
        for (long long v : d) {
            if (v < x) ans += v * v;
            else cnt++;
        }
        ans += cnt * x * x;
        if (x > 0) ans -= (K - cost(x)) * (2 * x - 1);
        return ans;
    }
};

