class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        long[] d = new long[n];
        for (int i = 0; i < n; i++) d[i] = Math.abs((long) nums1[i] - nums2[i]);
        long K = (long) k1 + k2;
        java.util.function.LongUnaryOperator cost = x -> {
            long s = 0;
            for (long v : d) if (v > x) s += v - x;
            return s;
        };
        long lo = 0, hi = 0;
        for (long v : d) hi = Math.max(hi, v);
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (cost.applyAsLong(mid) <= K) hi = mid; else lo = mid + 1;
        }
        long x = lo, ans = 0, cnt = 0;
        for (long v : d) { if (v < x) ans += v * v; else cnt++; }
        ans += cnt * x * x;
        if (x > 0) ans -= (K - cost.applyAsLong(x)) * (2 * x - 1);
        return ans;
    }
}

