        if (cost(mid) <= K) hi = mid; else lo = mid + 1;
    }
    const x = lo;
    let ans = 0, cnt = 0;
    for (const v of d) { if (v < x) ans += v * v; else cnt++; }
    ans += cnt * x * x;
    if (x > 0) ans -= (K - cost(x)) * (2 * x - 1);
    return ans;
};

