class Solution:
    def minSumSquareDiff(self, nums1: List[int], nums2: List[int], k1: int, k2: int) -> int:
        cnt = Counter(abs(a - b) for a, b in zip(nums1, nums2))
        ops = k1 + k2
        for v in range(max(cnt, default=0), 0, -1):
            c = cnt.get(v, 0)
            if not c:
                continue
            m = min(c, ops)
            cnt[v] -= m
            cnt[v - 1] += m
            ops -= m
            if ops == 0:
                break
        return sum(v * v * c for v, c in cnt.items())

