class Solution {
public:
    long long minSumSquareDiff(vector<int>& nums1, vector<int>& nums2, int k1, int k2) {
        int n = nums1.size(), mx = 0;
        vector<long long> cnt(100001, 0);
        for (int i = 0; i < n; ++i) {
            long long dv = abs(nums1[i] - nums2[i]);
            cnt[dv]++; mx = max(mx, (int)dv);
        }
        long long ops = (long long)k1 + k2;
        for (int v = mx; v >= 1 && ops > 0; --v) {
            long long m = min(cnt[v], ops);
            cnt[v] -= m; cnt[v - 1] += m; ops -= m;
        }
        long long ans = 0;
        for (int v = 0; v <= 100000; ++v) ans += cnt[v] * v * v;
        return ans;
    }
};

